#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <assert.h>

typedef struct splay_node {
    int key;
    struct splay_node *left;
    struct splay_node *right;
    struct splay_node *parent;
} splay_node;

splay_node *root = NULL;

void left_rotate(splay_node *x) {
    splay_node *y = x->right;
    if (y) {
        x->right = y->left;
        if (y->left) y->left->parent = x;
        y->parent = x->parent;
    }
    if (!x->parent) root = y;
    else if (x == x->parent->left) x->parent->left = y;
    else x->parent->right = y;
    if (y) y->left = x;
    x->parent = y;
}

void right_rotate(splay_node *x) {
    splay_node *y = x->left;
    if (y) {
        x->left = y->right;
        if (y->right) y->right->parent = x;
        y->parent = x->parent;
    }
    if (!x->parent) root = y;
    else if (x == x->parent->left) x->parent->left = y;
    else x->parent->right = y;
    if (y) y->right = x;
    x->parent = y;
}

void splay_node_ptr(splay_node *n) {
    while (n->parent) {
        if (!n->parent->parent) {
            if (n->parent->left == n) right_rotate(n->parent);
            else left_rotate(n->parent);
        } else if (n->parent->left == n && n->parent->parent->left == n->parent) {
            right_rotate(n->parent->parent);
            right_rotate(n->parent);
        } else if (n->parent->right == n && n->parent->parent->right == n->parent) {
            left_rotate(n->parent->parent);
            left_rotate(n->parent);
        } else if (n->parent->left == n && n->parent->parent->right == n->parent) {
            right_rotate(n->parent);
            left_rotate(n->parent);
        } else {
            left_rotate(n->parent);
            right_rotate(n->parent);
        }
    }
}

void splay(int key) {
    if (!root) return;
    splay_node *curr = root;
    splay_node *last = NULL;
    while (curr) {
        last = curr;
        if (curr->key == key) {
            splay_node_ptr(curr);
            return;
        } else if (key < curr->key) {
            curr = curr->left;
        } else {
            curr = curr->right;
        }
    }
    if (last) {
        splay_node_ptr(last);
    }
}

void splay_insert(int key) {
    if (!root) {
        splay_node* n = (splay_node*)malloc(sizeof(splay_node));
        n->key = key;
        n->left = n->right = n->parent = NULL;
        root = n;
        return;
    }
    splay(key);
    if (root->key == key) return;
    splay_node* n = (splay_node*)malloc(sizeof(splay_node));
    n->key = key;
    n->parent = NULL;
    if (key < root->key) {
        n->right = root;
        n->left = root->left;
        if (n->left) n->left->parent = n;
        root->left = NULL;
        root->parent = n;
    } else {
        n->left = root;
        n->right = root->right;
        if (n->right) n->right->parent = n;
        root->right = NULL;
        root->parent = n;
    }
    root = n;
}

void splay_delete(int key) {
    if (!root) return;
    splay(key);
    if (root->key != key) return;
    splay_node *del = root;
    if (!root->left) {
        root = root->right;
        if (root) root->parent = NULL;
    } else {
        splay_node *left_tree = root->left;
        splay_node *right_tree = root->right;
        left_tree->parent = NULL;
        root = left_tree;
        splay_node *m = left_tree;
        while (m->right) m = m->right;
        splay_node_ptr(m);
        root->right = right_tree;
        if (right_tree) right_tree->parent = root;
    }
    free(del);
}

bool is_bst(splay_node* n, splay_node** prev) {
    if (!n) return true;
    if (!is_bst(n->left, prev)) return false;
    if (*prev && (*prev)->key >= n->key) return false;
    *prev = n;
    return is_bst(n->right, prev);
}

void check_invariants() {
    splay_node *prev = NULL;
    assert(is_bst(root, &prev));
}

int main() {
    for (int i = 0; i < 10000; i++) {
        int op = rand() % 3;
        int k = rand() % 1000;
        if (op == 0) {
            splay_insert(k);
            assert(root->key == k);
        } else if (op == 1) {
            splay(k);
        } else {
            splay_delete(k);
        }
        check_invariants();
    }
    printf("FLAG: Splay Tree Success!\n");
    return 0;
}
